const currentDate = new Date();
const reminderDate = new Date();
reminderDate.setDate(currentDate.getDate() + 3);

const feeRecords = $input.all();
const reminders = [];

for (const record of feeRecords) {
  const feeData = record.json;
  const dueDate = new Date(feeData.dueDate);

  if (dueDate <= reminderDate && dueDate > currentDate) {
    const paymentLink = `https://payments.school.edu/pay?student=${feeData.studentId}&amount=${feeData.amount}&ref=${feeData.feeId}`;

    reminders.push({
      studentName: feeData.studentName,
      parentName: feeData.parentName,
      parentEmail: feeData.parentEmail,
      parentPhone: feeData.parentPhone,
      feeType: feeData.feeType,
      amount: feeData.amount,
      dueDate: feeData.dueDate,
      feeId: feeData.feeId,
      paymentLink: paymentLink,
      daysRemaining: Math.ceil((dueDate - currentDate) / (1000 * 60 * 60 * 24))
    });
  }
}

return reminders.map(item => ({ json: item }));

const feeData = $input.first().json;

const emailSubject = `Fee Reminder: ${feeData.feeType} Due in ${feeData.daysRemaining} days`;
const emailBody = `Dear ${feeData.parentName},

This is a friendly reminder that the ${feeData.feeType} for ${feeData.studentName} is due on ${feeData.dueDate}.

Fee Details:
- Student: ${feeData.studentName}
- Fee Type: ${feeData.feeType}
- Amount: $${feeData.amount}
- Due Date: ${feeData.dueDate}
- Days Remaining: ${feeData.daysRemaining}

💳 PAY NOW: ${feeData.paymentLink}

To avoid late fees, please complete payment before the due date. If you have any questions, contact our finance office.

Thank you,
School Finance Office`;

return [{
  json: {
    to: feeData.parentEmail,
    subject: emailSubject,
    body: emailBody,
    parentName: feeData.parentName,
    studentName: feeData.studentName,
    paymentLink: feeData.paymentLink
  }
}];

